\copy (SELECT json_build_object('id', id, 'subject', subject_area, 'exam', exam_type, 'q', question_text, 'a', option_a, 'b', option_b, 'c', option_c, 'd', option_d, 'e', option_e, 'key', correct_answer) FROM question_bank WHERE is_active = true AND quality_review_status = 'unverified' AND correct_answer IN ('A','B','C','D','E') AND option_a IS NOT NULL AND option_b IS NOT NULL AND option_c IS NOT NULL AND option_d IS NOT NULL AND option_e IS NOT NULL AND word_count >= 8 AND pipeline_metadata->>'verified_provisional' IS DISTINCT FROM 'true' ORDER BY md5(id) LIMIT 3000) TO 'C:/Users/husey/kiro2/backend/scripts/quality/_pool_growth_wave1/master.csv' CSV
